import{_ as e,o as s,c as a,ag as i}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Part 9 — Caching (deep dive)","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_09_Caching.md","filePath":"todo/study_plan/parts/Part_09_Caching.md"}'),n={name:"todo/study_plan/parts/Part_09_Caching.md"};function d(r,t,o,c,l,h){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="part-9-—-caching-deep-dive" tabindex="-1">Part 9 — Caching (deep dive) <a class="header-anchor" href="#part-9-—-caching-deep-dive" aria-label="Permalink to &quot;Part 9 — Caching (deep dive)&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 5 (shared). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_9-caching-—-topic-inventory" tabindex="-1">9 Caching — topic inventory <a class="header-anchor" href="#_9-caching-—-topic-inventory" aria-label="Permalink to &quot;9 Caching — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Patterns — cache-aside, read-through, write-through, write-behind, refresh-ahead</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>~45 min (ChatGPT). Refresh-ahead pending; write-around covered as bonus</td><td>📖 <code>system_design/caching/CachingAndDistributedCache.md</code></td></tr><tr><td>2</td><td>Invalidation strategies — TTL, explicit, event-driven</td><td>🔴 💼 🎯</td><td>MP</td><td>1 hr 45 min</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: explicit delete-vs-update on write covered; TTL + event-driven strategies pending</td><td>📖 <code>system_design/caching/CachingAndDistributedCache.md</code> (explicit only) · 💻 Warm-up: cache-aside with TTL using Spring <code>@Cacheable(unless=...)</code> + explicit eviction via <code>@CacheEvict</code> (15 min)</td></tr><tr><td>3</td><td>Eviction policies — LRU, LFU, ARC, FIFO, random</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: LRU concept covered; LFU/ARC/FIFO details pending</td><td>📖 <code>system_design/caching/CachingAndDistributedCache.md</code> (LRU only)</td></tr><tr><td>4</td><td>Cache stampede / thundering herd — single-flight, request coalescing, jittered TTLs</td><td>🔴 💼 🎯</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>Spring <code>@Cacheable</code> mechanics + pitfalls — self-invocation bypass (AOP proxy), SpEL key, <code>sync = true</code> for hot keys, condition vs unless, CacheManager wiring</td><td>🔴 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: reproduce the self-invocation trap — service method calls another method with @Cacheable on same class, observe cache bypass; fix via self-injection or AspectJ (30 min)</td></tr><tr><td>6</td><td>Multi-tier caching — browser, CDN, gateway, app, distributed, DB buffer</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: local→Redis→DB layering + CPU-cache analogy + CDN tier covered; full browser/gateway/DB-buffer tier walk pending</td><td>📖 <code>system_design/caching/CachingAndDistributedCache.md</code> + <code>system_design/cdn/Cdn.md</code> (partial)</td></tr><tr><td>7</td><td>Negative caching (caching &quot;not found&quot;)</td><td>🟠 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Cache consistency models in microservices</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Hot key problem &amp; mitigation</td><td>🟠 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Cache key design — tenant-scoped, versioned, collision-safe (e.g., <code>kyc:v1:tenant:{tenantId}:doc:{docId}</code>); cross-tenant safety; key versioning for schema migrations</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Redis specifically — data structures, persistence (RDB/AOF), Sentinel, Cluster</td><td>🟠 💼</td><td>D</td><td>3 hrs 20 min</td><td>[ ]</td><td>[x]</td><td>[ ]</td><td>[ ]</td><td>Partial: Cluster (16384 hash slots, masters/replicas, failover) covered; data structures, RDB/AOF, Sentinel pending</td><td>📖 <code>system_design/caching/CachingAndDistributedCache.md</code> (Cluster only) · 📖 redis.io intro · 💻 Warm-up: connect with <code>redis-cli</code>, exercise SET/GET/EXPIRE/TTL/HSET/LPUSH/ZADD from memory (20 min)</td></tr><tr><td>12</td><td>Memcached vs Redis tradeoffs</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Caffeine (in-JVM cache) — for Spring apps</td><td>🟠</td><td>MP</td><td>1 hr 35 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Caffeine builder with maximumSize + expireAfterWrite + recordStats (20 min)</td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~10.25 hrs</td><td>~0.93 wk</td><td>~45 min so far (row 1 done; rows 2, 3 partial)</td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~21 hrs</td><td>~1.9 wk</td><td>~45 min so far (rows 6, 11 also partial)</td></tr><tr><td>Full Part (all items including 🟡)</td><td>~21.83 hrs</td><td>~2 wk</td><td>~45 min so far</td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>Cache patterns — write semantics:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph CA[Cache-aside / Lazy-load]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A1[App reads cache] --&gt;|miss| A2[App reads DB]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A2 --&gt; A3[App writes cache]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A4[App writes DB] -.-&gt;|app responsible| A5[App invalidates cache]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph WT[Write-through]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B1[App writes] --&gt; B2[Cache writes]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B2 --&gt; B3[Cache writes DB synchronously]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph WB[Write-behind / Write-back]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C1[App writes] --&gt; C2[Cache writes]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C2 -.-&gt;|async, batched| C3[Cache flushes to DB later]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><blockquote><p>Cache-aside is the most common (app owns cache logic). Write-through gives consistency at write-latency cost. Write-behind sacrifices durability for performance.</p></blockquote><p><strong>Cache stampede — the failure mode:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant T1 as Thread 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant T2 as Thread 2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant TN as Thread N</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as Cache</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant D as DB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over T1,TN: TTL expires for key K</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T1-&gt;&gt;C: get(K) → miss</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T2-&gt;&gt;C: get(K) → miss</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TN-&gt;&gt;C: get(K) → miss</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T1-&gt;&gt;D: SELECT * WHERE...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T2-&gt;&gt;D: SELECT * WHERE...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TN-&gt;&gt;D: SELECT * WHERE...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over D: 💥 N concurrent expensive queries</span></span></code></pre></div><blockquote><p>Fix: single-flight (only one thread loads, others wait), request coalescing, or jittered TTLs so keys don&#39;t expire simultaneously.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through 5 cache write patterns (cache-aside, read-through, write-through, write-behind, refresh-ahead). When does each fit? <ul><li><strong>Why asked:</strong> Senior-canonical. Cache-aside (most common, app-managed); read-through (cache fetches on miss); write-through (sync write); write-behind (async, batched, durability risk); refresh-ahead (proactive renewal for hot keys before TTL).</li></ul></li><li><strong>Q:</strong> Cache stampede — what is it, what causes it, three mitigations? <ul><li><strong>Why asked:</strong> Tail-latency canonical. Cause: many threads simultaneously miss a popular key (TTL expired or first request). Mitigations: (1) single-flight / mutex around DB call, (2) jittered TTL so keys don&#39;t expire together, (3) probabilistic early refresh before TTL expires.</li></ul></li><li><strong>Q:</strong> Compare LRU vs LFU eviction. When does each win? <ul><li><strong>Why asked:</strong> Eviction-policy literacy. LRU: assumes recently-used = likely-needed; works well for sequential access patterns. LFU: assumes frequently-used = important; works well when access patterns are stable. LFU pathological case: long-tail cold items can never be evicted. ARC adapts between them.</li></ul></li><li><strong>Q:</strong> Negative caching — when do you cache &quot;not found&quot;? <ul><li><strong>Why asked:</strong> Common subtle optimization. When DB lookups for missing keys are expensive AND missing keys are common (e.g., bot traffic). Caveat: bounded TTL on negative entries (so a new entry isn&#39;t permanently &quot;missing&quot;). Don&#39;t negative-cache if keys are likely to be created soon (e.g., new user profile during onboarding).</li></ul></li><li><strong>Q:</strong> Hot key problem in Redis Cluster — what is it, mitigations? <ul><li><strong>Why asked:</strong> Real production headache. Single key gets disproportionate traffic → single shard overloaded. Mitigations: (1) replicate hot key across shards, (2) split hot key into many sub-keys (<code>key:shard1</code> ... <code>key:shardN</code>), (3) client-side caching of hot keys (Spring Caffeine in front of Redis), (4) tag-based sharding via hash tags.</li></ul></li><li><strong>Q:</strong> Multi-tier caching — design the cache layers for your KYC platform&#39;s verification status read path. <ul><li><strong>Why asked:</strong> Architecture exercise. Likely: client SDK (60s TTL) → API gateway / CloudFront (10s TTL) → app-level Caffeine (1s TTL) → Redis distributed cache → DB. Each layer has different consistency budgets.</li></ul></li><li><strong>Q:</strong> Redis persistence options — RDB vs AOF, when to use each? <ul><li><strong>Why asked:</strong> Operational depth. RDB: point-in-time snapshots, smaller files, faster restart, but data loss between snapshots. AOF: append every write, larger but more durable, slower restart. AOF + <code>appendfsync everysec</code> is a common production sweet spot.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your cache TTL is 1 hour. Why does adding &quot;jitter&quot; matter? <ul><li><strong>Gotcha:</strong> Without jitter, all keys written in the same minute expire in the same minute — and reload concurrently (stampede). Jitter: actual_ttl = base_ttl + random(0, 0.1 × base_ttl) (10% jitter). Spreads expiration evenly.</li></ul></li><li><strong>Q:</strong> You set up cache-aside. After a write to DB, you forget to invalidate the cache. The user sees stale data for an hour. How would you architect to avoid this? <ul><li><strong>Gotcha:</strong> Common bug. Architecture options: (1) write-through (eliminate manual invalidation), (2) event-driven invalidation (DB change events → cache eviction), (3) much shorter TTL (sacrifice cache hit rate for staleness bound), (4) cache key includes a &quot;version&quot; or &quot;updated_at&quot; that&#39;s checked on read.</li></ul></li><li><strong>Q:</strong> Redis MSET on 4 keys — is this atomic across keys? <ul><li><strong>Gotcha:</strong> Yes, MSET is atomic (single-threaded Redis). But in Redis Cluster, keys may live on different shards — MSET fails unless all keys are in the same slot. Use <code>{tag}</code> hash tags to force same-slot for related keys: <code>user:{42}:name</code>, <code>user:{42}:email</code>.</li></ul></li><li><strong>Q:</strong> You added Caffeine cache in front of an expensive operation. Cache hit rate is 95% but P99 latency is unchanged. Why? <ul><li><strong>Gotcha:</strong> The 5% misses dominate P99 because percentiles measure the slow tail. If misses are slow (say 500ms) and hits are fast (1ms), and you have 95% hits, P99 still sees the misses. Fix: reduce miss latency (cache more, eager warming, or improve the miss path itself).</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Cache stampede + mitigation strategies</strong> (~2.5 hrs) — interview-canonical. Implement single-flight in Java (one approach: <code>ConcurrentHashMap&lt;Key, CompletableFuture&lt;Value&gt;&gt;</code>). Add jittered TTL helper.</li><li><strong>Multi-tier cache design for your KYC platform</strong> (~2 hrs) — concrete cache layer design with TTLs, consistency budgets, invalidation triggers. Becomes a portable artifact for design discussions.</li><li><strong>5 cache patterns walkthrough with concrete code</strong> (~3 hrs) — implement all 5 patterns in a small Spring service. Compare write latency, miss path, durability semantics.</li><li><strong>Redis data structures + hot key mitigation</strong> (~2.5 hrs) — strings, hashes, sorted sets, streams. Plus hot-key replication strategy with hash tags.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up cache exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Reproduce cache stampede + fix</strong> (~60 min) — Spring service with <code>@Cacheable</code> on a slow method (sleep 500ms). Load test with 100 concurrent users hitting same cache key. Observe N concurrent DB calls when TTL expires. Fix with <code>synchronized</code> or <code>ConcurrentHashMap&lt;Key, CompletableFuture&lt;Value&gt;&gt;</code>-based single-flight.</li><li><strong>Implement LRU cache from scratch</strong> (~45 min) — <code>HashMap&lt;K, Node&gt; + Doubly Linked List</code>. Put / get / evict. Verify O(1) operations. Compare to <code>LinkedHashMap</code> with <code>accessOrder=true</code> + <code>removeEldestEntry()</code>.</li><li><strong>Negative caching with bounded TTL</strong> (~30 min) — wrapper around <code>UserRepository.findById()</code> that caches <code>Optional.empty()</code> results with 10-second TTL. Verify it skips DB on cache hit. Confirm short TTL so new users aren&#39;t permanently negative-cached.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>Multi-tier cache for KYC verification status read</strong> (~90 min) — design + implement: Caffeine in-process (TTL 1s) → Redis distributed (TTL 60s) → DB. Verify hit rates at each layer under load. Decide invalidation strategy.</li><li><strong>Redis hot key replication via hash tags</strong> (~60 min) — simulate a hot key receiving 10× more traffic than others. Spread it across N replicas via <code>key:{shard1}</code> ... <code>key:{shardN}</code> with client-side fan-out. Measure load distribution.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.25 hrs</td><td>~0.2 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~4.75 hrs</strong></td><td><strong>~0.45 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~1 hr 25 min for Part 9 across 4 in-table warm-ups (adds the @Cacheable self-invocation reproduction).</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Cache-aside in one sentence.</strong> A. App reads cache first; on miss, app reads DB and writes cache; on write, app writes DB then invalidates (or updates) cache. Most common pattern; app owns the cache logic.</p><p><strong>Q. Stampede — three mitigations.</strong> A. (1) Single-flight / mutex so only one thread loads the missing key. (2) Jittered TTL so keys don&#39;t expire simultaneously. (3) Probabilistic early refresh before TTL expires.</p><p><strong>Q. LRU vs LFU — when LFU wins.</strong> A. LFU wins when access patterns are stable and a few hot items dominate access (the items get high frequency counts and stay in cache). Loses on access-pattern shifts (a new hot item can&#39;t beat the old high-frequency ones to stay resident).</p><p><strong>Q. Why use jitter on TTL?</strong> A. Without jitter, all keys written in the same window expire together — concurrent reload thundering herd. Jitter (10-20% random) spreads expirations evenly.</p><p><strong>Q. Redis hash tags syntax — what&#39;s it for?</strong> A. <code>user:{42}:name</code> — the <code>{42}</code> portion is the hash tag; all keys with same tag land on same Redis Cluster slot. Enables multi-key ops (MSET, MGET, MULTI/EXEC) across related keys.</p><p><strong>Q. Negative caching gotcha?</strong> A. Cache &quot;not found&quot; with bounded TTL (10-60 seconds), not the long TTL of positive entries. Otherwise newly-created entities appear missing for hours.</p>`,35)])])}const u=e(n,[["render",d]]);export{g as __pageData,u as default};
